import React from "react";

const View: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ children, style, ...props }) => (
  <div style={{ display: "flex", ...style }} {...props}>
    {children}
  </div>
);

const Text: React.FC<React.HTMLAttributes<HTMLSpanElement>> = ({ children, style, ...props }) => (
  <span style={style} {...props}>{children}</span>
);

function App() {
  return (
    <View style={{ justifyContent: "center", alignItems: "center", height: "100vh" }}>
      <Text style={{ fontSize: "24px", fontWeight: "bold" }}>Hello World!</Text>
    </View>
  );
}

export default App;
